(async()=>{try{const q=EmberQA,T=THREE,n=q.world.native;q.setPlaying(false);const scene=new T.Scene();scene.background=new T.Color('#b6cbd1');scene.add(new T.HemisphereLight('#ffffff','#777777',1.4));const group=new T.Group();scene.add(group);const geometry=new T.PlaneGeometry(800,800,100,100);geometry.rotateX(-Math.PI/2);const p=geometry.attributes.position,coords=[],covers=[],sands=[],colors=[];const east=211,north=191;
for(let i=0;i<p.count;i++){const x=p.getX(i)+east,z=p.getZ(i)+north,y=NatureWorld.height(x,z),s=NatureWorld.surfaceSample(x,z,y);p.setY(i,y);coords.push(x,y,z);covers.push(...s.cover);sands.push(s.sand);colors.push(s.tint.r,s.tint.g,s.tint.b);}geometry.setAttribute('terrainLocation',new T.Float32BufferAttribute(coords,3));geometry.setAttribute('groundCover',new T.Float32BufferAttribute(covers,3));geometry.setAttribute('sandCover',new T.Float32BufferAttribute(sands,1));geometry.setAttribute('color',new T.Float32BufferAttribute(colors,3));geometry.computeVertexNormals();const mesh=new T.Mesh(geometry,n.terrainMaterial);group.add(mesh);const camera=new T.PerspectiveCamera(60,1.5,.1,3000);camera.position.set(30,340,420);camera.lookAt(0,30,0);q.renderer.setSize(900,600);q.renderer.shadowMap.enabled=false;
// Wait for the existing image textures, then compare the same ground before/after rebasing.
await new Promise(resolve=>{const timer=setInterval(()=>{if(Object.values(n.originals).every(t=>t.image?.complete)&&n.atlas.image?.complete){clearInterval(timer);resolve();}},100);});const target=new T.WebGLRenderTarget(600,400),a=new Uint8Array(600*400*4),b=new Uint8Array(a.length);q.renderer.setRenderTarget(target);q.renderer.render(scene,camera);q.renderer.readRenderTargetPixels(target,0,0,600,400,a);n.offset.x+=1024;n.offset.z-=1024;group.position.set(1024,0,-1024);mesh.position.set(-1024,0,1024);q.renderer.render(scene,camera);q.renderer.readRenderTargetPixels(target,0,0,600,400,b);let changed=0;for(let i=0;i<a.length;i++)if(a[i]!==b[i])changed++;q.renderer.setRenderTarget(null);q.renderer.render(scene,camera);const screenshot=q.renderer.domElement.toDataURL();q.setPlaying(false);const panel=document.createElement('section');panel.style='position:fixed;inset:0;z-index:9999;background:#10282d;overflow:auto;padding:20px';panel.innerHTML='<h1 style="font:24px sans-serif">地面の固定・境界ブレンド描画確認</h1><p id="result">'+(changed===0?'PASS':'FAIL')+' — 原点を1024m移動しても変わった画素成分：'+changed+'</p><img style="max-width:100%" src="'+screenshot+'">';document.body.appendChild(panel);}catch(error){document.body.innerHTML='<pre>FAIL '+error.stack+'</pre>';}})();
